31	async function probeConsoleAndRequests(page: Page, vpName: string, bugs: Bug[]) {
32	  const consoleErrors: string[] = [];
33	  const consoleWarns: string[] = [];
34	  const pageErrors: string[] = [];
35	  const failedRequests: { url: string; reason: string }[] = [];
36	  const slow: { url: string; ms: number }[] = [];
37	
38	  page.on("console", (msg) => {
39	    const t = msg.type();
40	    const text = msg.text();
41	    if (t === "error") consoleErrors.push(text);
42	    else if (t === "warning") consoleWarns.push(text);
43	  });
44	  page.on("pageerror", (err) => pageErrors.push(err.message));
45	  page.on("requestfailed", (req) => {
46	    failedRequests.push({ url: req.url(), reason: req.failure()?.errorText ?? "" });
47	  });
48	  page.on("response", (resp) => {
49	    const status = resp.status();
50	    if (status >= 400 && resp.url().startsWith(LOCAL)) {
51	      failedRequests.push({ url: resp.url(), reason: `HTTP ${status}` });
52	    }
53	  });
54	
55	  return {
56	    finalize: () => {
57	      for (const e of consoleErrors) {
58	        // Skip 3rd-party 429 rate-limit noise
59	        if (e.includes("429") || e.includes("Failed to load resource")) continue;
60	        if (e.includes("hydrated but some attributes")) {
61	          pushBug(bugs, { category: "hydration", severity: "major", viewport: vpName, message: e.slice(0, 250) });
62	        } else {
63	          pushBug(bugs, { category: "console-error", severity: "major", viewport: vpName, message: e.slice(0, 250) });
64	        }
65	      }
66	      for (const w of consoleWarns) {
67	        if (w.includes("Download the React DevTools")) continue;
68	        if (w.toLowerCase().includes("react") || w.toLowerCase().includes("next") || w.includes("Image")) {
69	          pushBug(bugs, { category: "console-warn", severity: "minor", viewport: vpName, message: w.slice(0, 250) });
70	        }
71	      }
72	      for (const e of pageErrors) {
73	        pushBug(bugs, { category: "page-error", severity: "critical", viewport: vpName, message: e.slice(0, 300) });
74	      }
75	      for (const r of failedRequests) {
76	        if (r.url.includes("trustpilot") || r.url.includes("guidejar") || r.url.includes("clarity") || r.url.includes("google-analytics") || r.url.includes("contentsquare") || r.url.includes("chatwoot")) continue;
77	        pushBug(bugs, { category: "failed-request", severity: "major", viewport: vpName, message: `${r.reason} ${r.url}` });
78	      }
79	      return { consoleErrors, consoleWarns, pageErrors, failedRequests, slow };
80	    },
81	  };
82	}
