84	async function checkA11y(page: Page, vpName: string, bugs: Bug[]) {
85	  const findings = await page.evaluate(() => {
86	    type F = { type: string; selector: string; detail?: string };
87	    const out: F[] = [];
88	
89	    // 1. Missing alt
90	    document.querySelectorAll("img").forEach((img, i) => {
91	      if (!img.hasAttribute("alt")) out.push({ type: "img-no-alt", selector: `img:nth-of-type(${i + 1})`, detail: img.src.slice(-80) });
92	    });
93	
94	    // 2. Multiple H1
95	    const h1s = document.querySelectorAll("h1");
96	    if (h1s.length === 0) out.push({ type: "no-h1", selector: "body" });
97	    if (h1s.length > 1) out.push({ type: "multiple-h1", selector: "body", detail: `${h1s.length} h1 elements` });
98	
99	    // 3. Heading hierarchy skip (h1 then h3 without h2)
100	    const headings = Array.from(document.querySelectorAll("h1,h2,h3,h4,h5,h6"));
101	    let prev = 0;
102	    for (const h of headings) {
103	      const lvl = parseInt(h.tagName[1]!, 10);
104	      if (prev > 0 && lvl > prev + 1) out.push({ type: "heading-skip", selector: h.tagName.toLowerCase(), detail: `${prev}→${lvl}: "${h.textContent?.trim().slice(0, 60)}"` });
105	      prev = lvl;
106	    }
107	
108	    // 4. Form inputs without label
109	    document.querySelectorAll("input:not([type='hidden']),textarea,select").forEach((el, i) => {
110	      const id = el.getAttribute("id");
111	      const ariaLabel = el.getAttribute("aria-label");
112	      const ariaLabelledby = el.getAttribute("aria-labelledby");
113	      const hasLabel = id ? !!document.querySelector(`label[for="${id}"]`) : false;
114	      const wrapped = el.closest("label") !== null;
115	      if (!hasLabel && !ariaLabel && !ariaLabelledby && !wrapped) {
116	        const tag = el.tagName.toLowerCase();
117	        const type = el.getAttribute("type") ?? "";
118	        out.push({ type: "input-no-label", selector: `${tag}[${type}]:nth-of-type(${i + 1})`, detail: el.getAttribute("name") ?? "" });
119	      }
120	    });
121	
122	    // 5. Buttons / links without accessible name
123	    document.querySelectorAll("button, a").forEach((el, i) => {
124	      const text = (el.textContent ?? "").trim();
125	      const ariaLabel = el.getAttribute("aria-label");
126	      const ariaLabelledby = el.getAttribute("aria-labelledby");
127	      const titleAttr = el.getAttribute("title");
128	      if (!text && !ariaLabel && !ariaLabelledby && !titleAttr) {
129	        const inner = el.querySelector("img[alt],svg[aria-label]");
130	        if (!inner) out.push({ type: "no-accessible-name", selector: `${el.tagName.toLowerCase()}:nth-of-type(${i + 1})` });
131	      }
132	    });
133	
134	    // 6. Empty href / href="#" non-anchor links
135	    document.querySelectorAll("a").forEach((el, i) => {
136	      const href = el.getAttribute("href");
137	      if (!href || href === "#" || href === "javascript:void(0)" || href === "javascript:void(0);") {
138	        out.push({ type: "dead-link", selector: `a:nth-of-type(${i + 1})`, detail: `href="${href}" text="${el.textContent?.trim().slice(0, 40)}"` });
139	      }
140	    });
141	
142	    // 7. External links without rel="noopener noreferrer"
143	    document.querySelectorAll('a[target="_blank"]').forEach((el, i) => {
144	      const rel = el.getAttribute("rel") ?? "";
145	      if (!rel.includes("noopener") || !rel.includes("noreferrer")) {
146	        out.push({ type: "external-no-rel", selector: `a[target=_blank]:nth-of-type(${i + 1})`, detail: el.getAttribute("href") ?? "" });
147	      }
148	    });
149	
150	    // 8. Images without explicit width/height (causes CLS)
151	    document.querySelectorAll("img").forEach((img, i) => {
152	      const w = img.getAttribute("width");
153	      const h = img.getAttribute("height");
154	      if (!w || !h) out.push({ type: "img-no-dimensions", selector: `img:nth-of-type(${i + 1})`, detail: img.src.slice(-80) });
155	    });
156	
157	    // 9. Buttons without type
158	    document.querySelectorAll("button").forEach((b, i) => {
159	      if (!b.hasAttribute("type")) out.push({ type: "button-no-type", selector: `button:nth-of-type(${i + 1})` });
160	    });
161	
162	    // 10. Modals / dialogs missing aria-modal
163	    document.querySelectorAll('[role="dialog"]').forEach((d, i) => {
164	      if (d.getAttribute("aria-modal") !== "true") out.push({ type: "dialog-no-aria-modal", selector: `[role=dialog]:nth-of-type(${i + 1})` });
165	      if (!d.getAttribute("aria-labelledby") && !d.getAttribute("aria-label")) out.push({ type: "dialog-no-label", selector: `[role=dialog]:nth-of-type(${i + 1})` });
166	    });
167	
168	    // 11. Click handler on non-interactive element
169	    document.querySelectorAll("[onclick]").forEach((el, i) => {
170	      const tag = el.tagName.toLowerCase();
171	      if (!["button", "a", "input", "textarea", "select"].includes(tag) && el.getAttribute("role") !== "button") {
172	        out.push({ type: "click-on-non-interactive", selector: `${tag}:nth-of-type(${i + 1})` });
173	      }
174	    });
175	
176	    // 12. tabindex > 0 (anti-pattern)
177	    document.querySelectorAll("[tabindex]").forEach((el, i) => {
178	      const ti = parseInt(el.getAttribute("tabindex") ?? "0", 10);
179	      if (ti > 0) out.push({ type: "positive-tabindex", selector: `${el.tagName.toLowerCase()}:nth-of-type(${i + 1})`, detail: `tabindex=${ti}` });
180	    });
181	
182	    // 13. Page lang
183	    if (!document.documentElement.lang) out.push({ type: "no-lang", selector: "html" });
184	
185	    return out;
186	  });
187	
188	  for (const f of findings) {
189	    let severity: Bug["severity"] = "minor";
190	    if (["page-error", "no-h1", "no-lang"].includes(f.type)) severity = "critical";
191	    if (["multiple-h1", "input-no-label", "no-accessible-name", "dead-link", "img-no-alt", "dialog-no-aria-modal"].includes(f.type)) severity = "major";
192	    if (["heading-skip", "external-no-rel", "img-no-dimensions"].includes(f.type)) severity = "minor";
193	    pushBug(bugs, { category: `a11y/${f.type}`, severity, viewport: vpName, selector: f.selector, message: f.detail ?? "" });
194	  }
195	}
