197	async function checkSeo(page: Page, vpName: string, bugs: Bug[]) {
198	  const findings = await page.evaluate(() => {
199	    type F = { type: string; detail: string };
200	    const out: F[] = [];
201	
202	    const title = document.querySelector("title")?.textContent ?? "";
203	    if (!title) out.push({ type: "no-title", detail: "" });
204	    if (title.length > 70) out.push({ type: "title-too-long", detail: `${title.length} chars` });
205	    if (title.length < 10) out.push({ type: "title-too-short", detail: `${title.length} chars` });
206	
207	    const desc = document.querySelector('meta[name="description"]')?.getAttribute("content") ?? "";
208	    if (!desc) out.push({ type: "no-description", detail: "" });
209	    if (desc.length > 170) out.push({ type: "description-too-long", detail: `${desc.length} chars` });
210	    if (desc.length < 100) out.push({ type: "description-too-short", detail: `${desc.length} chars` });
211	
212	    if (!document.querySelector('meta[property="og:title"]')) out.push({ type: "no-og-title", detail: "" });
213	    if (!document.querySelector('meta[property="og:description"]')) out.push({ type: "no-og-description", detail: "" });
214	    if (!document.querySelector('meta[property="og:image"]')) out.push({ type: "no-og-image", detail: "" });
215	    if (!document.querySelector('meta[name="twitter:card"]')) out.push({ type: "no-twitter-card", detail: "" });
216	    if (!document.querySelector('link[rel="canonical"]')) out.push({ type: "no-canonical", detail: "" });
217	
218	    const jsonld = document.querySelectorAll('script[type="application/ld+json"]');
219	    if (jsonld.length === 0) out.push({ type: "no-json-ld", detail: "" });
220	
221	    const viewport = document.querySelector('meta[name="viewport"]')?.getAttribute("content") ?? "";
222	    if (!viewport) out.push({ type: "no-viewport-meta", detail: "" });
223	
224	    return out;
225	  });
226	
227	  for (const f of findings) {
228	    pushBug(bugs, { category: `seo/${f.type}`, severity: f.type.startsWith("no-") ? "major" : "minor", viewport: vpName, message: f.detail });
229	  }
230	}
