232	async function checkPerf(page: Page, vpName: string, bugs: Bug[]) {
233	  const metrics = await page.evaluate(() => {
234	    const nav = performance.getEntriesByType("navigation")[0] as PerformanceNavigationTiming | undefined;
235	    const paint = performance.getEntriesByType("paint");
236	    const fcp = paint.find((p) => p.name === "first-contentful-paint");
