254	  const findings = await page.evaluate(() => {
255	    type F = { type: string; selector: string; detail: string };
256	    const out: F[] = [];
257	    const vw = window.innerWidth;
258	
259	    // 1. Horizontal overflow (any element wider than viewport)
260	    document.querySelectorAll<HTMLElement>("section, main, div, header, footer, nav").forEach((el, i) => {
261	      const r = el.getBoundingClientRect();
262	      if (r.width > vw + 1) {
263	        const cls = el.className?.toString().slice(0, 60) ?? "";
264	        out.push({ type: "horizontal-overflow", selector: `${el.tagName.toLowerCase()}.${cls}`, detail: `width=${Math.round(r.width)} > vw=${vw}` });
265	      }
266	    });
267	
268	    // 2. Tap target too small (mobile only — handled by viewport name check outside)
269	    document.querySelectorAll<HTMLElement>("button, a").forEach((el, i) => {
270	      const r = el.getBoundingClientRect();
271	      if (r.width === 0 || r.height === 0) return; // hidden
272	      if (r.width < 24 || r.height < 24) {
273	        if (window.innerWidth <= 768) {
274	          out.push({ type: "tap-target-tiny", selector: `${el.tagName.toLowerCase()}:nth-of-type(${i + 1})`, detail: `${Math.round(r.width)}×${Math.round(r.height)}` });
275	        }
276	      }
277	    });
278	
279	    // 3. Text overflow / clipping
280	    document.querySelectorAll<HTMLElement>("h1,h2,h3,h4,p,a,button,span").forEach((el, i) => {
281	      if (el.scrollWidth > el.clientWidth + 2) {
282	        const cs = window.getComputedStyle(el);
283	        if (cs.overflow === "hidden" && cs.textOverflow !== "ellipsis") {
284	          out.push({ type: "text-clipped", selector: `${el.tagName.toLowerCase()}:nth-of-type(${i + 1})`, detail: `scroll=${el.scrollWidth} client=${el.clientWidth}` });
285	        }
286	      }
287	    });
288	
289	    // 4. Text too small (under 12px)
290	    document.querySelectorAll<HTMLElement>("p, span, a, li, button").forEach((el) => {
291	      const r = el.getBoundingClientRect();
292	      if (r.width === 0 || r.height === 0) return;
293	      const fs = parseFloat(window.getComputedStyle(el).fontSize);
294	      if (fs < 11) out.push({ type: "text-too-small", selector: el.tagName.toLowerCase(), detail: `${fs}px` });
295	    });
296	
297	    // 5. Color contrast — sample headings
298	    function rgbToL(rgb: string): number {
299	      const m = rgb.match(/\d+/g);
300	      if (!m) return 0;
301	      const [r, g, b] = m.slice(0, 3).map((x) => {
302	        const v = parseInt(x, 10) / 255;
303	        return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
304	      });
305	      return 0.2126 * (r ?? 0) + 0.7152 * (g ?? 0) + 0.0722 * (b ?? 0);
306	    }
307	    function contrast(fg: string, bg: string): number {
308	      const l1 = rgbToL(fg);
309	      const l2 = rgbToL(bg);
310	      const a = Math.max(l1, l2);
311	      const b = Math.min(l1, l2);
312	      return (a + 0.05) / (b + 0.05);
313	    }
314	    function effectiveBg(el: HTMLElement): string {
315	      let cur: HTMLElement | null = el;
316	      while (cur) {
317	        const c = window.getComputedStyle(cur).backgroundColor;
318	        if (c && c !== "rgba(0, 0, 0, 0)" && c !== "transparent") return c;
319	        cur = cur.parentElement;
320	      }
321	      return "rgb(255,255,255)";
322	    }
323	    document.querySelectorAll<HTMLElement>("p, span, a, li, h1, h2, h3, h4, h5, h6, button").forEach((el, i) => {
324	      const r = el.getBoundingClientRect();
325	      if (r.width === 0 || r.height === 0) return;
326	      if ((el.textContent ?? "").trim().length === 0) return;
327	      const cs = window.getComputedStyle(el);
328	      const fg = cs.color;
329	      const bg = effectiveBg(el);
330	      const fs = parseFloat(cs.fontSize);
331	      const fw = parseInt(cs.fontWeight, 10) || 400;
332	      const isLarge = fs >= 24 || (fs >= 18.66 && fw >= 700);
333	      const ratio = contrast(fg, bg);
334	      const min = isLarge ? 3 : 4.5;
335	      if (ratio < min) {
336	        out.push({ type: "low-contrast", selector: `${el.tagName.toLowerCase()}:nth-of-type(${i + 1})`, detail: `ratio=${ratio.toFixed(2)} fg=${fg} bg=${bg} fs=${fs}px` });
337	      }
338	    });
