340	    return out;
341	  });
342	
343	  for (const f of findings) {
344	    let severity: Bug["severity"] = "minor";
345	    if (f.type === "horizontal-overflow") severity = "major";
346	    if (f.type === "tap-target-tiny") severity = "major";
347	    if (f.type === "text-clipped") severity = "minor";
